const now = new Date();
const weekEnd = new Date(now);
weekEnd.setHours(0,0,0,0);
const weekStart = new Date(weekEnd);
weekStart.setDate(weekEnd.getDate() - 6);
return [{ json: { week_start: weekStart.toISOString().split('T')[0], week_end: weekEnd.toISOString().split('T')[0] } }];

const jobs = $input.all();
if (jobs.length === 0) return [];

const byFacility = {};
jobs.forEach(item => {
  const j = item.json;
  if (!byFacility[j.facility_id]) {
    byFacility[j.facility_id] = { facility_id: j.facility_id, company_id: j.company_id, job_ids: [], jobs_completed: 0 };
  }
  byFacility[j.facility_id].job_ids.push(j.id);
  byFacility[j.facility_id].jobs_completed++;
});

const allJobIds = jobs.map(i => i.json.id).join(',');
return [{ json: { jobs_by_facility: byFacility, all_job_ids: allJobIds, week_start: $('Set Date Range').item.json.week_start, week_end: $('Set Date Range').item.json.week_end } }];

const zones = $input.all();
const jobsByFacility = $('Collect Job IDs').item.json.jobs_by_facility;

const zonesByFacility = {};
Object.entries(jobsByFacility).forEach(([facilityId, data]) => {
  const jobIds = data.job_ids;
  const fZones = zones.filter(z => jobIds.includes(z.json.job_id));
  zonesByFacility[facilityId] = {
    zones_completed: fZones.filter(z => z.json.status === 'completed').length,
    zones_flagged: fZones.filter(z => z.json.status === 'flagged_no_photo').length
  };
});

return [{ json: { zones_by_facility: zonesByFacility } }];

const logs = $input.all();
const jobsByFacility = $('Collect Job IDs').item.json.jobs_by_facility;
const zonesByFacility = $('Aggregate Zones').item.json.zones_by_facility;
const weekStart = $('Collect Job IDs').item.json.week_start;
const weekEnd = $('Collect Job IDs').item.json.week_end;

return Object.entries(jobsByFacility).map(([facilityId, data]) => {
  const jobIds = data.job_ids;
  const evidence_photos = logs.filter(l => jobIds.includes(l.json.job_id)).length;
  const zones = zonesByFacility[facilityId] || { zones_completed: 0, zones_flagged: 0 };
  return { json: {
    facility_id: facilityId,
    company_id: data.company_id,
    jobs_completed: data.jobs_completed,
    zones_completed: zones.zones_completed,
    zones_flagged: zones.zones_flagged,
    evidence_photos: evidence_photos,
    week_start: weekStart,
    week_end: weekEnd
  }};
});

var facilityName = $('Get Facility').item.json.name || 'your facility';
var managerId = $json.id;
var report = $('Build Reports').item.json;

var title = 'Weekly Cleaning Report Ready';
var message = 'Your weekly report for ' + facilityName + ' (' + report.week_start + ' – ' + report.week_end + ') is ready: ' + report.jobs_completed + ' jobs completed, ' + report.zones_completed + ' zones cleaned, ' + report.evidence_photos + ' photos logged.';

return [{ json: { user_id: managerId, title: title, message: message } }];
